import { expect, test } from 'bun:test';
import { resolve } from 'node:path';
import type { UseCase } from '@agentic-ddd/core';
import { OperatorRuntime, type ToolCall } from '@agentic-ddd/runtime';
import { covers, FakeLlm, InMemoryEventBus, type LlmScriptEntry } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';
import { TaskCreated, TaskCompleted } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';

async function setup(script: readonly LlmScriptEntry[]) {
  const tasks = new InMemoryTaskRepository();
  const llm = new FakeLlm(script);
  const eventBus = new InMemoryEventBus();
  const runtime = new OperatorRuntime({
    llm,
    eventBus,
    root: resolve(import.meta.dir, '../..'),
    modules: [{ name: 'tasks', path: 'app' }],
  });
  await runtime.register(TaskOperator, new Map<Function, UseCase<unknown, unknown>>([
    [CreateTask, new CreateTask(tasks)],
    [CompleteTask, new CompleteTask(tasks)],
  ]));
  return { tasks, llm, eventBus, runtime };
}

function toolCall(id: string, name: string, input: unknown): ToolCall {
  return { type: 'tool_call', id, name, input };
}

test(covers([
  'operator:task-operator',
  'criterion:0001/tools',
], 'executa somente create_task e complete_task, conclui a tarefa e publica os dois eventos'), async () => {
  const answer = 'A tarefa t1 foi criada e concluída.';
  const { tasks, llm, eventBus, runtime } = await setup([
    {
      stopReason: 'tool_calls',
      content: [toolCall('create-1', 'create_task', { task_id: 't1', title: '  Minha tarefa  ' })],
    },
    {
      stopReason: 'tool_calls',
      content: [toolCall('complete-1', 'complete_task', { task_id: 't1' })],
    },
    { stopReason: 'end', content: [{ type: 'text', text: answer }] },
  ]);
  expect(await tasks.findById('t1')).toBeNull();

  const result = await runtime.run('task-operator', {
    message: 'Crie a tarefa t1 com título Minha tarefa e conclua-a.',
  });

  expect(result.operator).toBe('task-operator');
  expect(result.status).toBe('completed');
  expect(result.output).toBe(answer);
  expect(llm.requests).toHaveLength(3);
  for (const request of llm.requests) {
    expect(request.tools.map(tool => tool.name).sort()).toEqual(['complete_task', 'create_task']);
    expect(request.system).toContain('Identifique a tarefa pelo id e responda em português.');
  }
  const toolSteps = result.steps.flatMap(step => step.tools);
  expect(toolSteps.map(step => step.call.name)).toEqual(['create_task', 'complete_task']);
  expect(toolSteps.map(step => step.policy)).toEqual(['allow', 'allow']);
  expect(toolSteps.map(step => step.result)).toEqual([
    {
      toolCallId: 'create-1',
      isError: false,
      content: {
        output: { task_id: 't1', title: 'Minha tarefa', status: 'pending' },
        events: [{ name: 'TaskCreated', payload: { taskId: 't1', title: 'Minha tarefa' } }],
      },
    },
    {
      toolCallId: 'complete-1',
      isError: false,
      content: {
        output: { task_id: 't1', status: 'completed' },
        events: [{ name: 'TaskCompleted', payload: { taskId: 't1' } }],
      },
    },
  ]);
  expect(llm.requests[1]!.messages.at(-1)).toEqual({ role: 'tool', results: [toolSteps[0]!.result!] });
  expect(llm.requests[2]!.messages.at(-1)).toEqual({ role: 'tool', results: [toolSteps[1]!.result!] });

  const saved = await tasks.findById('t1');
  expect(saved).not.toBeNull();
  expect(saved!.id).toBe('t1');
  expect(saved!.title).toBe('Minha tarefa');
  expect(saved!.status).toBe('completed');
  expect(saved!.pullEvents()).toEqual([]);
  expect(eventBus.events).toHaveLength(2);
  expect(eventBus.events[0]).toBeInstanceOf(TaskCreated);
  expect(eventBus.events[1]).toBeInstanceOf(TaskCompleted);
  expect(eventBus.events.map(event => event.payload)).toEqual([
    { taskId: 't1', title: 'Minha tarefa' },
    { taskId: 't1' },
  ]);
  expect(result.events).toEqual(eventBus.events);
  expect(toolSteps.map(step => step.events)).toEqual([[eventBus.events[0]], [eventBus.events[1]]]);
});

test(covers(['operator:task-operator'], 'rejeita tool fora da lista e entrada inválida sem salvar ou publicar'), async () => {
  const { tasks, eventBus, runtime } = await setup([
    {
      stopReason: 'tool_calls',
      content: [
        toolCall('unknown-1', 'delete_task', { task_id: 't1' }),
        toolCall('invalid-1', 'create_task', { task_id: 't1' }),
      ],
    },
    { stopReason: 'end', content: [{ type: 'text', text: 'Não foi possível alterar a tarefa t1.' }] },
  ]);

  const result = await runtime.run('task-operator', { message: 'Altere a tarefa t1.' });

  expect(result.status).toBe('completed');
  const toolSteps = result.steps.flatMap(step => step.tools);
  expect(toolSteps).toHaveLength(2);
  expect(toolSteps[0]!.result).toEqual({
    toolCallId: 'unknown-1',
    isError: true,
    content: { code: 'unknown_tool', name: 'delete_task' },
  });
  expect(toolSteps[1]!.result).toMatchObject({
    toolCallId: 'invalid-1',
    isError: true,
    content: { code: 'invalid_input' },
  });
  expect(await tasks.findById('t1')).toBeNull();
  expect(eventBus.events).toEqual([]);
  expect(result.events).toEqual([]);
});
